theorem exists_innerSolidTorus_toroidalShell_of_annulusImage
    {P : Fin 4 → EuclideanSpace ℝ (Fin 3)} {D Dint : Fin 3 → Set (EuclideanSpace ℝ (Fin 3))}
    {J : Fin 4 → Set (EuclideanSpace ℝ (Fin 3))} {A S T : Fin 3 → Set (EuclideanSpace ℝ (Fin 3))}
    {N : Set (EuclideanSpace ℝ (Fin 3))} {h : EuclideanSpace ℝ (Fin 3) → EuclideanSpace ℝ (Fin 3)}
    (hc : IsRevolvedTorusChain P D Dint J A S T) (hN : N = ⋃ j, S j)
    (hh : IsEmbedding (N.domRestrict h)) (j : Fin 3) :
    ∃ S₁ : Set (EuclideanSpace ℝ (Fin 3)), IsTopologicalSolidTorus S₁ ∧
      h '' A j ⊆ interior S₁ ∧ S₁ ⊆ interior (h '' S j) ∧
      IsToroidalShell (closure (h '' S j \ S₁)) (frontier S₁) (frontier (h '' S j))

theorem compactTargetRecognition (hcut : Section34CompactCutFrame C K K' src srcBd)
    (hgraph : Section34CompactGraphFrame V h ε K K' src H f₁)
    {fbl fblBd : Section34CompactSimplexIndex K 3 → Set (EuclideanSpace ℝ (Fin 3))}
    (hinv : Section34CompactFaceBallInvariants K K' h H
      (section34CompactVertexBallImage src f₁) (section34CompactSplitDiskImage srcBd f₁)
      fbl fblBd)
    {tgtD tgtDBd : Section34CompactSimplexIndex K 3 → Set (EuclideanSpace ℝ (Fin 3))}
    {tgtA tgtABd : Section34CompactArcIndex K K' → Set (EuclideanSpace ℝ (Fin 3))}
    {tgtP : Section34CompactMarkIndex K K' → Set (EuclideanSpace ℝ (Fin 3))}
    (hdisk : Section34CompactFaceDiskFamily K K' (section34CompactVertexBallImage src f₁)
      (section34CompactSplitDiskImage src f₁) (section34CompactSplitDiskImage srcBd f₁)
      fblBd tgtD tgtDBd tgtA tgtABd tgtP)
    {tgtR tgtRBd : Section34CompactSimplexIndex K 4 → Set (EuclideanSpace ℝ (Fin 3))}
    {tgtX tgtXBd : Section34CompactPatchIndex K K' → Set (EuclideanSpace ℝ (Fin 3))}
    {tgtI tgtIBd : Section34CompactEdgeArcIndex K K' → Set (EuclideanSpace ℝ (Fin 3))}
    {tgtO tgtOBd : Section34CompactOuterVertexIndex K K' → Set (EuclideanSpace ℝ (Fin 3))}
    {tgtQ tgtQBd : Section34CompactOuterEdgeIndex K K' → Set (EuclideanSpace ℝ (Fin 3))}
    (hres : Section34CompactResidualPlus K K' H (section34CompactVertexBallImage src f₁)
      (section34CompactVertexBallImage srcBd f₁) (section34CompactSplitDiskImage src f₁)
      (section34CompactSplitDiskImage srcBd f₁) tgtD tgtA tgtP tgtR tgtRBd tgtX tgtXBd
      tgtI tgtIBd tgtO tgtOBd tgtQ tgtQBd)
    (hface : ∀ l m : Section34CompactLabelOf K K', src m ⊆ src l ↔ Section34CompactCutLe m l)
    (tc tcBd : Section34CompactLabelOf K K' → Set (EuclideanSpace ℝ (Fin 3)))
    (htc : tc = section34BoundedCell (section34CompactVertexBallImage src f₁) tgtR
      (section34CompactSplitDiskImage src f₁) tgtD tgtX tgtA tgtI tgtP tgtO tgtQ)
    (htcBd : tcBd = section34BoundedCell (section34CompactVertexBallImage srcBd f₁) tgtRBd
      (section34CompactSplitDiskImage srcBd f₁) tgtDBd tgtXBd tgtABd tgtIBd (fun _ => ∅)
      tgtOBd tgtQBd) :
    (∀ l, tcBd l = ⋃ m ∈ section34Face src l \ {l}, tc m) ∧
      ∀ l m, tc l ∩ tc m = ⋃ k ∈ section34Face src l ∩ section34Face src m, tc k

theorem wallProductBlock_transport [T2Space M] {f : EuclideanSpace ℝ (Fin 2) → M}
    {S : Set (EuclideanSpace ℝ (Fin 2))} {ι : Type}
    {ec : ι → OpenPartialHomeomorph M (EuclideanSpace ℝ (Fin 3))}
    {ℓ : ι → (EuclideanSpace ℝ (Fin 3) →ₗ[ℝ] ℝ)} {Eb Eb' : ι → Set M} {BdM C N : Set M}
    {Q : Geometry.SimplicialComplex ℝ Ea} {ρ : M → Ea} {Cf Bf : Set (Finset Ea)}
    {A : EuclideanSpace ℝ (Fin 3) ≃ᵃ[ℝ] ℝ × ℝ × ℝ} {r tlo : ℝ}
    {SA SB : Set (EuclideanSpace ℝ (Fin 2))} {a b : ℝ × ℝ → ℝ} {La Lb η : ℝ} {y : M}
    (hsys : IsCommonWallSystem Q ρ Cf Bf BdM C ec ℓ Eb Eb') (i i' : ι)
    (h : WallProductBlock f S (ec i) (ℓ i) BdM C Q ρ A r tlo SA SB a b La Lb η)
    (hmapC : MapsTo f S C) (hblkE : chartBlock (ec i) A r tlo ⊆ Eb i)
    (hy : y ∈ innerChartBlock (ec i) A r tlo) (hy' : y ∈ Eb i')
    (hN : IsOpen N) (hyN : y ∈ N) :
    ∃ (A' : EuclideanSpace ℝ (Fin 3) ≃ᵃ[ℝ] ℝ × ℝ × ℝ) (r' tlo' : ℝ)
      (SA' SB' : Set (EuclideanSpace ℝ (Fin 2))) (a' b' : ℝ × ℝ → ℝ),
      WallProductBlock f S (ec i') (ℓ i') BdM C Q ρ A' r' tlo' SA' SB' a' b' La Lb η ∧
        A' (ec i' y) = 0 ∧ y ∈ innerChartBlock (ec i') A' r' tlo' ∧
        chartBlock (ec i') A' r' tlo' ⊆ N ∩ chartBlock (ec i) A r tlo

theorem hasStableCrossingBlocks_of_wallProductBlocks [T2Space M]
    {f : EuclideanSpace ℝ (Fin 2) → M} {S : Set (EuclideanSpace ℝ (Fin 2))} {ι : Type}
    {ec : ι → OpenPartialHomeomorph M (EuclideanSpace ℝ (Fin 3))}
    {ℓ : ι → (EuclideanSpace ℝ (Fin 3) →ₗ[ℝ] ℝ)} {Eb Eb' : ι → Set M}
    {BdM C Z Z' : Set M} {Q : Geometry.SimplicialComplex ℝ Ea} {ρ : M → Ea}
    {Cf Bf : Set (Finset Ea)} {η κ : ℝ}
    (hsys : IsCommonWallSystem Q ρ Cf Bf BdM C ec ℓ Eb Eb')
    (h : HasWallProductBlocks f S ec ℓ Eb BdM C Q ρ Z η)
    (hScpt : IsCompact S) (hcont : ContinuousOn f S) (hmapC : MapsTo f S C)
    (hκ : 0 < κ) (hinj : UniformInjectivityScale S f κ)
    (i₀ : ι) (hZ'cpt : IsCompact Z') (hZ'Z : Z' ⊆ Z) (hZ'E : Z' ⊆ interior (Eb i₀)) :
    HasStableCrossingBlocks f S (ec i₀) (ℓ i₀) BdM Z' η
